import math


class ParallelSmaAndRsiStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity("SPY", Resolution.Daily, Market.USA, False).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily, Market.USA, False).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily, Market.USA, False).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily, Market.USA, False).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily, Market.USA, False).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_bars = RollingWindow[TradeBar](201)
        self.aapl_bars = RollingWindow[TradeBar](4)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data):
        received = {}

        for symbol in self.symbols:
            if not data.Bars.ContainsKey(symbol):
                continue

            bar = data.Bars[symbol]
            if bar is None or getattr(bar, "IsFillForward", False):
                continue

            received[symbol] = bar

            if symbol == self.spy:
                self.spy_bars.Add(bar)
            elif symbol == self.aapl:
                self.aapl_bars.Add(bar)
                self.aapl_rsi.Update(bar.EndTime, bar.Close)

        if len(received) != len(self.symbols):
            return

        spy_bar = received[self.spy]
        aapl_bar = received[self.aapl]

        # Evaluate all sells before any buys.
        if self.strategy_a_shares > 0 and self._strategy_a_ready():
            if self._crosses_below_sma50():
                self.MarketOrder(self.spy, -self.strategy_a_shares)
                self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and self.aapl_rsi.IsReady:
            if self.aapl_rsi.Current.Value > 60:
                self.MarketOrder(self.aapl, -self.strategy_b_shares)
                self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and self._strategy_a_ready():
            if self._crosses_above_sma200():
                quantity = int(
                    math.floor(
                        float(self.Portfolio.TotalPortfolioValue) * 0.40 /
                        float(spy_bar.Close)
                    )
                )
                if quantity > 0:
                    self.MarketOrder(self.spy, quantity)
                    self.strategy_a_shares = quantity

        if self.strategy_b_shares == 0 and self._strategy_b_ready():
            if self._aapl_red_for_three_days():
                if self.Portfolio.Cash >= 20_000:
                    quantity = int(math.floor(20_000 / float(aapl_bar.Close)))
                    if quantity > 0:
                        self.MarketOrder(self.aapl, quantity)
                        self.strategy_b_shares = quantity

    def _strategy_a_ready(self):
        return self.spy_bars.IsReady and self.spy_bars.Count >= 201

    def _strategy_b_ready(self):
        return self.aapl_bars.IsReady and self.aapl_bars.Count >= 4 and self.aapl_rsi.IsReady

    def _crosses_above_sma200(self):
        today_close = self.spy_bars[0].Close
        yesterday_close = self.spy_bars[1].Close

        today_sma = sum(self.spy_bars[i].Close for i in range(200)) / 200
        yesterday_sma = sum(self.spy_bars[i].Close for i in range(1, 201)) / 200

        return yesterday_close <= yesterday_sma and today_close > today_sma

    def _crosses_below_sma50(self):
        today_close = self.spy_bars[0].Close
        yesterday_close = self.spy_bars[1].Close

        today_sma = sum(self.spy_bars[i].Close for i in range(50)) / 50
        yesterday_sma = sum(self.spy_bars[i].Close for i in range(1, 51)) / 50

        return yesterday_close >= yesterday_sma and today_close < today_sma

    def _aapl_red_for_three_days(self):
        return (
            self.aapl_bars[0].Close < self.aapl_bars[1].Close and
            self.aapl_bars[1].Close < self.aapl_bars[2].Close and
            self.aapl_bars[2].Close < self.aapl_bars[3].Close
        )
