            self.previous_aapl_close = current_aapl_close

        if self.IsWarmingUp:
            return

        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        if (
            self.close_windows[self.spy].Count < 201
            or self.close_windows[self.aapl].Count < 201
            or not self.aapl_rsi.IsReady
        ):
            return

        spy_closes = self.close_windows[self.spy]
        spy_close_today = spy_closes[0]
        spy_close_yesterday = spy_closes[1]

        sma200_today = sum(spy_closes[i] for i in range(200)) / 200.0
        sma200_yesterday = sum(spy_closes[i] for i in range(1, 201)) / 200.0

