        sma50_yesterday = sum(spy_closes[i] for i in range(1, 51)) / 50.0

        aapl_close = float(data.Bars[self.aapl].Close)

        if self.strategy_a_lot > 0:
            if (
                spy_close_yesterday >= sma50_yesterday
                and spy_close_today < sma50_today
            ):
                self.MarketOrder(self.spy, -self.strategy_a_lot)
                self.strategy_a_lot = 0

        if self.strategy_b_lot > 0:
            if float(self.aapl_rsi.Current.Value) > 60:
                self.MarketOrder(self.aapl, -self.strategy_b_lot)
                self.strategy_b_lot = 0

        if self.strategy_a_lot == 0:
            if (
                spy_close_yesterday <= sma200_yesterday
                and spy_close_today > sma200_today
            ):
                quantity = int(
                    math.floor(
                        0.40 * float(self.Portfolio.TotalPortfolioValue)
                        / spy_close_today
                    )
                )
                if quantity > 0:
                    self.MarketOrder(self.spy, quantity)
                    self.strategy_a_lot = quantity

        if self.strategy_b_lot == 0:
            if self.aapl_red_streak >= 3 and float(self.Portfolio.Cash) >= 20_000:
                quantity = int(math.floor(20_000 / aapl_close))
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)
                    self.strategy_b_lot = quantity
